arguments.command:
cat > /tmp/git-askpass-friends.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) echo "x-access-token" ;;
  *) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod 700 /tmp/git-askpass-friends.sh
GIT_ASKPASS=/tmp/git-askpass-friends.sh git -C /tmp/friends-conv-phoebe push origin HEAD:refs/heads/friend/phoebe 2>&1 | tail -5
